        let x = layout.x(for: owner.playhead).rounded()
        guard x >= owner.pinnedX + TimelineLayout.headerWidth else { return }
        DS.playhead.setFill()
        let head = NSBezierPath()
        head.move(to: NSPoint(x: x - 5, y: bounds.height - 10))
