    // MARK: Summary

    /// The label column of the summary rows. Deliberately NOT
    /// `InspectorMetrics.labelWidth` (76): these labels are whole words
    /// ("Resolution", "Frame rate", "Background") where the clip panes' are
    /// single properties, and widening the shared metric would re-flow every
    /// row in every other pane to fix five rows here.
    private static let summaryLabelWidth: CGFloat = 86

    /// What the document IS, read-only, before the controls that change it
    /// (handoff README, Part 2 §5). The tab used to open on a size popup,
    /// which answers "what can I set" before "what am I looking at".
    ///
    /// The sixth row, Colour, is the design's: the project's dynamic range,
    /// `canvas.output` (spec §11 HD-2, HD-13 (k)), "SDR — Rec. 709" or "HDR —
    /// Rec. 2100 HLG", set by the Canvas section's Dynamic Range popup.
    private func summarySection() -> InspectorSection {
        let binding = self.binding
        if settings.audioBits == 24 { lpcm[AVLinearPCMBitDepthKey] = 24 }
        if settings.container.lowercased() == "aiff" { lpcm[AVLinearPCMIsBigEndianKey] = true }
        return lpcm
    }

    /// Whether this container can hold a chapter track (see `addChapters`).
    /// The QuickTime family and nothing else: a chapter list is a text track
    /// associated with the movie's own, and WAV, AIFF and the two image
    /// formats have no track to associate it with.
    static func carriesChapters(_ settings: ExportSettings) -> Bool {
        switch settings.container.lowercased() {
        case "mov", "quicktime", "mp4", "m4v", "m4a": return true
